// conditionBlocks returns the list of condition strings that should each be
// emitted as a separate `if <cond> { ... }` block sharing the same body.
// An AbsentOrEmptyCondition yields two entries (its two branches); every other
// condition yields a single entry.
func (g *CUEGenerator) conditionBlocks(cond Condition) []string {
	if aoe, ok := cond.(*AbsentOrEmptyCondition); ok {
		branches := aoe.Branches()
