// isMapKeyNodeName reports whether a field-tree node name denotes a bracket
// map-key access (e.g. "[app.oam.dev/name]") as opposed to an array index
// (e.g. "[0]") or a plain field.
func isMapKeyNodeName(name string) bool {
	if !strings.HasPrefix(name, "[") || !strings.HasSuffix(name, "]") {
		return false
	}
	content := name[1 : len(name)-1]
	if content == "" {
		return false
	}
	for _, d := range content {
		if d < '0' || d > '9' {
			return true
		}
	}
	return false // all digits → array index
}

