// writeValidatorBody writes the `name: { "msg": true; if fail { "msg": false } }`
// block at the given depth. An AbsentOrEmpty fail condition emits one
// false-assignment block per branch.
func (g *CUEGenerator) writeValidatorBody(sb *strings.Builder, v *Validator, depth int) {
	indent := strings.Repeat(g.indent, depth)
	inner := strings.Repeat(g.indent, depth+1)

