	check("String.LenGt", g.conditionToCUE(String("name").LenGt(5)),
		`parameter["name"] != _|_ if len(parameter["name"]) > 5`)
	check("Array.Contains", g.conditionToCUE(Array("tags").Contains("gpu")),
		`parameter["tags"] != _|_ if list.Contains(parameter["tags"], "gpu")`)
	check("Map.HasKey", g.conditionToCUE(Map("config").HasKey("debug")),
		`parameter["config"] != _|_ && parameter["config"].debug != _|_`)
	check("Array.IsNotEmpty", g.conditionToCUE(Array("tags").IsNotEmpty()),
		`parameter["tags"] != _|_ if len(parameter["tags"]) > 0`)
	check("Map.IsNotEmpty", g.conditionToCUE(Map("config").IsNotEmpty()),
		`parameter["config"] != _|_ if len(parameter["config"]) > 0`)

	// AllConditions with a chained guard joins with " if ".
	all := AllConditions(String("a").IsSet(), Array("tags").IsNotEmpty())
	check("AllConditions chained", g.conditionToCUE(all),
		`parameter["a"] != _|_ if parameter["tags"] != _|_ if len(parameter["tags"]) > 0`)

	// AllConditions without chained guard joins with " && ".
	all2 := AllConditions(String("a").IsSet(), String("b").IsSet())
	check("AllConditions plain", g.conditionToCUE(all2),
		`parameter["a"] != _|_ && parameter["b"] != _|_`)

